# Content for the discipline tracks in the Clinical Academy.
# Shape: TRACKS = [ {key, icon, hue, label, title, blurb, scope:[...], modules:[ {title, lede, lessons:[L,L,L]} x4 ], sources:[...] } ]
# Lesson L = (title, [para, para], [key, key], stem, [A, B, C, D], answer_letter, feedback)
# Every lesson is 4 minutes; three lessons per module = 12 minutes, the cap.

GP = dict(key='t-gp', icon='ph:stethoscope-duotone', hue=35, label='Track 1', title='General practice',
  blurb='Recognise, establish a safe baseline, titrate against measured targets, and hold continuity of care.',
  scope=['Screen and assess adults, and know when complexity means referring on.', 'Record a cardiovascular and substance-use baseline before any prescription.', 'Titrate against two or three problems the patient chose, not against a dose ceiling.', 'Rules on who may diagnose and prescribe differ by state and territory. Check your own authority before acting on anything here.'],
  modules=[
   dict(title='Recognise and triage', lede='Who to assess, what else it could be, and when to refer on.', lessons=[
    ('Who to screen', ['Adult ADHD rarely arrives labelled. It arrives as repeated job loss, chronic disorganisation, anxiety or depression that only half responds to treatment, or a parent who recognises themselves in their child’s assessment.', 'The six-question ASRS Part A is a screen, not a diagnosis. A positive screen earns a full assessment: current symptoms, impairment in more than one setting, and evidence that several symptoms were present before age 12.'],
     ['ASRS Part A: four or more responses in the shaded range means assess further.', 'DSM-5-TR for adults: five or more symptoms in a domain, several present before age 12, impairment in two or more settings.'],
     'A 34-year-old scores five of six on ASRS Part A. What comes next?', ['Diagnose ADHD and start treatment', 'A full assessment including developmental history and collateral', 'Reassure her that screens over-call', 'Order cognitive testing before anything else'], 'B', 'A screen opens the question. History across the lifespan, impairment and collateral answer it.'),
    ('What else could it be', ['Anxiety, depression, bipolar disorder, trauma, sleep apnoea, thyroid disease and substance use can all look like inattention. They also commonly sit alongside ADHD, so finding one does not exclude the other.', 'The most useful question is about time course. ADHD is lifelong and trait-like. Mood disorders come in episodes with a before and an after. Ask about sleep and substances in every assessment, because both are common, treatable amplifiers.'],
     ['Lifelong and trait-like points towards ADHD. Distinct episodes point towards a mood disorder.', 'Sleep and substance use are asked about every time, not only when suspected.'],
     'A patient describes two-week stretches of needing three hours of sleep, feeling unstoppable and overspending, separated by ordinary months. What is the priority?', ['Start a stimulant and review in a month', 'Treat as anxiety first', 'Assess for bipolar disorder before considering a stimulant', 'Order a sleep study'], 'C', 'Episodic elevated mood needs assessing first. Stimulants can destabilise untreated bipolar disorder.'),
    ('When to refer on', ['Most adult ADHD can be managed in primary care where your state allows it. Refer when the picture is complex: psychosis or bipolar disorder, active substance dependence, significant cardiac disease, pregnancy, or real diagnostic uncertainty.', 'A good referral says what you found, what you are unsure of, and what you want answered. It also says what you will keep doing in the meantime, so the patient is not left waiting with nothing.'],
     ['Refer for: psychosis, bipolar disorder, active dependence, significant cardiac disease, pregnancy, diagnostic doubt.', 'State the question you want answered, and what you will continue meanwhile.'],
     'Which patient most clearly needs specialist input before treatment starts?', ['A 28-year-old with ADHD symptoms and well-controlled asthma', 'A 40-year-old with ADHD symptoms and mild, treated hypertension', 'A 35-year-old who drinks two coffees a day', 'A 31-year-old with ADHD symptoms and a recent psychotic episode'], 'D', 'Psychosis is a clear trigger for specialist assessment before any stimulant is considered.')]),
   dict(title='Baseline and safety', lede='What to measure and ask before the first prescription.', lessons=[
    ('The cardiovascular baseline', ['Stimulants produce small average rises in heart rate and blood pressure. For most adults that is unimportant. For a few it matters, and you only know which if you measured first.', 'Record blood pressure, heart rate and weight. Ask about chest pain or fainting on exertion, palpitations, known heart disease, and any family history of sudden death under 40. An ECG is not routine; it is for when the history or examination raises a question.'],
     ['Before starting: blood pressure, heart rate, weight, cardiac history, family history of early sudden death.', 'ECG and cardiology opinion when the history or examination flags risk, not for everyone.'],
     'A 42-year-old has normal blood pressure and no symptoms, but his brother died suddenly at 36. What is the right step?', ['Seek cardiology advice before starting a stimulant', 'Start at a low dose and recheck in a month', 'An ECG is never needed in adults', 'Decline to treat his ADHD'], 'A', 'A family history of early sudden death is exactly the flag that warrants cardiac assessment first.'),
    ('Substances and safe prescribing', ['Ask about alcohol, cannabis, nicotine, caffeine and other stimulants without judgement. Substance use is more common in untreated ADHD, and treating ADHD well tends to lower that risk rather than raise it.', 'Where misuse or diversion is a concern, long-acting formulations are harder to misuse than immediate-release tablets. Check your state’s real-time prescription monitoring system before prescribing a controlled medicine, and agree on one prescriber and one pharmacy.'],
     ['Long-acting formulations carry lower misuse potential than immediate-release.', 'Check real-time prescription monitoring every time you prescribe a controlled medicine.'],
     'A patient with past amphetamine misuse, two years abstinent, has clear ADHD. What is the most defensible plan?', ['Refuse all medication permanently', 'Immediate-release dexamfetamine as needed', 'A long-acting formulation or non-stimulant, with monitoring and an agreed plan', 'Treat only with counselling'], 'C', 'Past misuse changes the choice of medicine and the monitoring, not the right to treatment.'),
    ('Pregnancy, contraception and other medicines', ['Ask about pregnancy plans before starting. The decision to continue medication in pregnancy is individual and belongs with a specialist and the patient, so it is better discussed before conception than after.', 'Check the full medicine list. Monoamine oxidase inhibitors are contraindicated with stimulants. Decongestants, and some antidepressants, can add to blood pressure and heart rate effects. Ask about supplements and energy drinks as well.'],
     ['Stimulants and monoamine oxidase inhibitors must not be combined.', 'Pregnancy planning is part of the first conversation for anyone who could become pregnant.'],
     'A patient on a stable stimulant tells you she is planning a pregnancy next year. Best response?', ['Tell her to stop the medication today', 'Say the medication is definitely safe', 'Wait until she is pregnant to raise it', 'Arrange specialist advice now so she can decide before conceiving'], 'D', 'The discussion is individual and works best before conception, with specialist input.')]),
   dict(title='Titration and review', lede='Dose against measured targets, fix what is fixable, and know when to change course.', lessons=[
    ('Start low and measure', ['Before the first dose, agree on two or three problems the patient most wants to change, and rate each from 0 to 10. Those ratings, repeated at each step, are what you titrate against.', 'Increase in small steps at sensible intervals and ask about coverage: when does the medicine start to work, and when does it wear off? The aim is the lowest dose that gives a worthwhile effect across the hours that matter.'],
     ['Two or three patient-chosen targets, rated 0 to 10, repeated at each review.', 'Ask about onset and wear-off times, not just “is it working”.'],
     'At review a patient says the medicine “sort of works”. What is the most useful next question?', ['Whether she would like a higher dose', 'How her target ratings have changed, and when the effect wears off', 'Whether she has read about other medicines', 'Whether her friends notice a difference'], 'B', 'Targets and coverage tell you whether to adjust dose, timing or formulation.'),
    ('Side effects you can fix', ['Appetite loss is the commonest complaint. Eating a proper breakfast before the dose and a substantial evening meal usually solves it. Weigh at each review.', 'Trouble falling asleep is often a timing problem: move the dose earlier or shorten the coverage. Late-afternoon irritability usually means the medicine is wearing off. Persistent rises in blood pressure or heart rate mean reduce, change or seek advice, not watch and hope.'],
     ['Weigh at every review. Appetite loss is managed with timing of meals first.', 'Insomnia: look at dose timing before adding anything for sleep.'],
     'A patient taking a long-acting stimulant at 10.30am cannot fall asleep before 1am. First step?', ['Add a sedative at night', 'Stop the stimulant', 'Move the dose earlier and review sleep in two weeks', 'Reassure her it will pass'], 'C', 'Timing is the first lever. A late-morning dose can still be active at midnight.'),
    ('When it is not working', ['Before raising the dose again, check the basics: is it being taken, at the right time, with adequate sleep? Is an untreated mood or anxiety disorder, or alcohol, accounting for what remains?', 'If a well-run trial of one stimulant class fails or is not tolerated, the other class is a reasonable next step, then non-stimulants such as atomoxetine or guanfacine. Medication is one part of treatment: skills-based psychological therapy and practical supports carry much of the rest.'],
     ['Check adherence, timing, sleep and comorbidity before escalating.', 'Failed one stimulant class: try the other before concluding stimulants do not work.'],
     'A patient has had no benefit from an adequate methylphenidate trial, taken reliably. What is the reasonable next step?', ['Trial an amfetamine-class medicine', 'Double the methylphenidate above the usual range', 'Conclude that she does not have ADHD', 'Stop all treatment'], 'A', 'Response to the two stimulant classes differs between individuals. Trying the other is standard.')]),
   dict(title='Shared care and continuity', lede='Referrals that can be measured, a review rhythm, and continuity through change.', lessons=[
    ('The measurable referral', ['A referral to psychology, occupational therapy or exercise physiology works best when it asks a specific functional question and includes a baseline. “Mornings: leaves late four days in five” can be re-measured. “Help with ADHD” cannot.', 'Share one outcome measure across the team, such as the patient’s own goal ratings, so that everyone is looking at the same change.'],
     ['Name the function that fails, give the baseline, ask one question.', 'One shared measure across the team beats four separate ones.'],
     'Which referral to an occupational therapist is most useful?', ['“ADHD. Please see.”', '“Struggling generally, for assessment.”', '“Please advise on medication.”', '“Late to work four days in five; goal is on time four days in five. Please assess morning routine.”'], 'D', 'A baseline and a target make the referral measurable for everyone involved.'),
    ('The review rhythm', ['During titration, review often. Once stable, review at least every six to twelve months. At every review record blood pressure, heart rate and weight, and revisit the patient’s targets.', 'Once a year, ask whether the medicine is still needed and still helping at this dose. Life changes, and so does the demand on attention. A planned review is better than a prescription that simply rolls on.'],
     ['Every review: blood pressure, heart rate, weight, target ratings.', 'Annually: is this still needed, and is this still the right dose?'],
     'A patient stable for three years asks why she still needs reviews. Best answer?', ['Reviews are a legal formality only', 'They check the medicine is still safe, still needed and still working for her current life', 'She does not need them', 'They are only to renew the script'], 'B', 'Reviews track safety and ongoing benefit as circumstances change.'),
    ('Continuity through change', ['Care breaks down at transitions: a move interstate, a new job, pregnancy, a change of prescriber. Prescribing rules differ between states, so plan a move before the script runs out.', 'Give the patient a short written plan they hold themselves: diagnosis, current medicine and dose, what was tried before, who is in the team, and what to do if things slip. It is the single most useful thing for continuity.'],
     ['One prescriber, one pharmacy, one written plan the patient holds.', 'Plan interstate moves early: prescribing rules differ between jurisdictions.'],
     'A stable patient is moving interstate in two months. What helps most?', ['Tell him to find a new doctor when he arrives', 'Give him six months of scripts', 'A written summary and an early plan for a prescriber in the new state', 'Stop the medication before he moves'], 'C', 'Rules differ between states. A written summary and early planning prevent a gap in treatment.')]),
  ],
  sources=['Australian Evidence-Based Clinical Practice Guideline for ADHD (AADPA, 2022)', 'Adult ADHD Self-Report Scale (ASRS-v1.1), World Health Organization', 'Your state or territory health department: current prescribing authority for ADHD medicines'])

PSY = dict(key='t-psy', icon='ph:brain-duotone', hue=260, label='Track 2', title='Psychology',
  blurb='Assessment that holds up, ADHD-specific cognitive behavioural therapy, and the emotional side of ADHD.',
  scope=['Run a structured assessment that a colleague could follow and defend.', 'Deliver skills-based therapy designed for ADHD, not generic therapy with ADHD in the room.', 'Work with emotion, shame and late diagnosis without pathologising them.', 'Medication questions go to the prescriber. Your observations of response and side effects are valuable to them.'],
  modules=[
   dict(title='Assessment that holds up', lede='Structured interview, corroboration, and formulation rather than tick-boxes.', lessons=[
    ('The structured interview', ['A structured interview such as the DIVA-5 walks through each criterion with real examples from childhood and adult life. The examples are the evidence; a bare “yes” is not.', 'You are establishing three things: enough symptoms now, several symptoms before age 12, and impairment in more than one setting. Rating scales support that judgement. They do not replace it.'],
     ['Ask for a concrete example for every criterion you endorse.', 'Rating scales inform. The interview and history decide.'],
     'A client scores very high on a self-report ADHD scale. What does that tell you?', ['That she has ADHD', 'That a thorough assessment is warranted', 'That she is exaggerating', 'That no interview is needed'], 'B', 'Scales are sensitive but not specific. High scores also occur in anxiety, depression and sleep deprivation.'),
    ('Collateral and records', ['School reports, a parent’s recollections, or a partner’s account can corroborate childhood onset and current impairment. Comments such as “capable but does not apply herself” are often the most telling lines in an old report.', 'Absence of records does not rule ADHD out. Many adults have no documents and no living informant, and girls and bright children were often missed. Weigh what you have and say what you could not obtain.'],
     ['Seek collateral, and record what you tried to obtain and could not.', 'Missing childhood records lowers certainty. It does not exclude the diagnosis.'],
     'A 45-year-old has no school reports and both parents have died. How do you proceed?', ['Decline to assess', 'Diagnose on the rating scale alone', 'Tell her ADHD cannot be diagnosed in adults', 'Take a detailed developmental history, seek any other informant, and document the limits'], 'D', 'Thorough history plus transparent documentation of limits is the defensible path.'),
    ('Differential and formulation', ['Anxiety, depression, trauma, autism, bipolar disorder and sleep problems all overlap with ADHD, and all commonly co-occur with it. The task is not to pick one, but to explain how each contributes to what the person experiences.', 'A formulation states what is ADHD, what is something else, what makes it worse, and what has been holding things together. That is what makes the report useful to a prescriber and to the client.'],
     ['Overlap is the rule. Ask what each condition explains, not which one wins.', 'Name the compensations that have been working. They are part of the picture.'],
     'A client’s concentration problems began after a traumatic event two years ago, with no earlier difficulties. What is the most likely reading?', ['Classic ADHD', 'ADHD masked in childhood', 'The onset points away from ADHD and towards a trauma-related explanation', 'It cannot be assessed'], 'C', 'ADHD is developmental. New-onset inattention in adulthood needs another explanation first.')]),
   dict(title='Therapy built for ADHD', lede='What the evidence supports and the core skills it teaches.', lessons=[
    ('What the evidence supports', ['Randomised trials of cognitive behavioural therapy designed specifically for adult ADHD show moderate improvement in symptoms and functioning, including in people already on medication. The programmes are structured, skills-based and repetitive on purpose.', 'Generic supportive therapy does less for core ADHD difficulties. If the sessions do not leave the client with a system they practise between visits, it is probably not ADHD-specific therapy.'],
     ['ADHD-specific, skills-based therapy adds benefit on top of medication.', 'Every session ends with a specific, small practice task.'],
     'What most distinguishes ADHD-specific cognitive behavioural therapy from generic therapy?', ['It explicitly teaches and rehearses organisation, planning and attention skills', 'It avoids homework', 'It focuses on childhood', 'It is unstructured'], 'A', 'The active ingredient is structured skills practice, repeated until it holds.'),
    ('The core skills', ['Most programmes start with one calendar and one task list, used every day. Then: breaking tasks into a first step small enough to start, prioritising, and managing distraction by writing the intruding thought down and returning to the task.', 'Expect the system to collapse and plan for it. Restarting without self-criticism is itself a skill you are teaching.'],
     ['One calendar, one task list, checked at the same time each day.', 'The first step should be small enough to begin within two minutes.'],
     'A client keeps abandoning her planner after a bad week. What is the most helpful response?', ['Suggest she is not motivated', 'Move on to a different topic', 'Treat restarting as the skill, and agree on a simple restart routine', 'Give her a more complex system'], 'C', 'Lapses are expected. A rehearsed restart matters more than a perfect streak.'),
    ('Adaptive thinking', ['Years of missed deadlines produce predictable thoughts: “I’ll do it later”, “I work best under pressure”, “there’s no point starting”. Some are over-optimistic, some are self-critical, and both keep avoidance going.', 'Work with these thoughts as they arise around real tasks. The goal is accurate thinking that supports action, not positive thinking.'],
     ['Watch for over-optimistic thoughts as well as self-critical ones.', 'Test thoughts against real tasks in the week, not in the abstract.'],
     'A client says “I always work best at the last minute”. How do you work with it?', ['Agree and move on', 'Tell her she is wrong', 'Ignore it', 'Look together at what the last-minute pattern has actually cost and delivered, then test an earlier start once'], 'D', 'Collaborative testing against real outcomes is how these beliefs shift.')]),
   dict(title='Emotion, shame and late diagnosis', lede='The part of ADHD that the criteria leave out.', lessons=[
    ('Emotional dysregulation', ['Quick, intense emotions that are slow to settle are common in adult ADHD. A meta-analysis of adults found emotional dysregulation to be a core feature rather than a side issue, even though it is not in the diagnostic criteria.', 'Name it as part of ADHD. Many clients have been told for years that they are “too sensitive”, and an explanation that fits is itself therapeutic. Then teach the usual regulation skills, adapted to be short and concrete.'],
     ['Emotional dysregulation is common in adult ADHD and worth assessing directly.', 'Keep regulation skills brief, concrete and practised in session.'],
     'A client with ADHD describes sudden, intense anger that passes within an hour. What is the best initial framing?', ['A personality disorder', 'Emotional dysregulation, which is common in ADHD and can be worked on', 'Unrelated to ADHD', 'A reason to stop therapy'], 'B', 'Brief, reactive emotion is typical of ADHD. Assess further, but start from what is common.'),
    ('Rejection sensitivity', ['Many adults with ADHD describe intense pain at perceived criticism or rejection. “Rejection sensitive dysphoria” is a widely used phrase, but it is not a formal diagnosis and has little research behind it as a separate entity.', 'Validate the experience, and treat it as emotion regulation and interpersonal work. It often sits on a real history of criticism, which deserves to be acknowledged rather than argued with.'],
     ['The experience is real and common. The label is informal, not a diagnosis.', 'Decades of correction are often part of the cause. Acknowledge them.'],
     'A client asks whether she has “RSD”. What is an accurate, helpful answer?', ['It is a recognised diagnosis needing its own medication', 'It does not exist', 'The experience is real and common in ADHD, the label is informal, and it can be worked on', 'It means she has a mood disorder'], 'C', 'Validate the experience, be honest about the label, and offer a way to work on it.'),
    ('After a late diagnosis', ['A diagnosis in adulthood brings relief and grief together: relief at an explanation, grief for the years without one. Both can arrive in the same session.', 'Make room for it before moving to skills. Self-compassion is practical here, because shame drives avoidance and avoidance undoes every system you build.'],
     ['Relief and grief commonly arrive together after adult diagnosis.', 'Shame fuels avoidance. Addressing it is part of skills work, not a detour.'],
     'A newly diagnosed 50-year-old spends the session angry about “wasted decades”. What do you do?', ['Make space for the grief, and link self-compassion to the work ahead', 'Redirect firmly to the planner', 'Tell her not to dwell', 'End the session early'], 'A', 'Grief is part of late diagnosis. Working with it makes the practical work possible.')]),
   dict(title='Working with the team', lede='What to pass on, how to adapt sessions, and how to manage risk.', lessons=[
    ('Medication conversations', ['Clients will ask you about medication. Decisions about starting, stopping or changing it belong to the prescriber. Your role is to help the client describe what they notice and take it to that conversation.', 'With consent, tell the prescriber what you observe: changes in mood or anxiety, appetite or sleep, any sign of misuse. You often see the client more frequently than they do.'],
     ['Do not advise on dose or on stopping. Help the client raise it with the prescriber.', 'With consent, share observations of response and side effects.'],
     'A client says her medication makes her flat and asks whether to halve it. Best response?', ['Tell her to halve it', 'Tell her to stop', 'Say it is not your area and move on', 'Help her describe what she notices, and encourage and support a prompt review with her prescriber'], 'D', 'The observation is valuable. The dosing decision belongs with the prescriber.'),
    ('Adapting the session', ['Standard therapy assumes the skills ADHD impairs. Adapt the frame: a visible agenda, one main point per session, a written summary the client takes away, and reminders before appointments.', 'Agree on one shared outcome measure with the rest of the team, such as the client’s own goal ratings, and re-rate it regularly so that change is visible to everyone.'],
     ['Visible agenda, one main point, written summary, appointment reminders.', 'Re-rate the client’s own goals regularly and share the result.'],
     'A client regularly misses appointments and arrives without the agreed practice. What do you do first?', ['Discharge for non-attendance', 'Adapt the supports: reminders, written summaries, smaller tasks', 'Conclude she is not ready for therapy', 'Lengthen the sessions'], 'B', 'Missed sessions are the presenting problem showing up in the room. Adjust the scaffolding first.'),
    ('Risk', ['Adults with ADHD have higher rates of suicidal thoughts and self-harm than the general population, particularly with co-occurring depression, substance use or impulsivity. Ask directly. Asking does not increase risk.', 'Build a safety plan with anyone at risk, written and kept where it will be found. Escalate according to your service’s pathway, and tell the GP or prescriber.'],
     ['Ask about suicidal thoughts directly and routinely.', 'A written safety plan, shared with the treating team.'],
     'A client mentions in passing that “everyone would be better off without me”. What do you do?', ['Let it pass to preserve rapport', 'Change the subject', 'Ask directly about suicidal thoughts and assess risk now', 'Wait until next session'], 'C', 'A remark like this is a cue to ask directly and assess now.')]),
  ],
  sources=['Australian Evidence-Based Clinical Practice Guideline for ADHD (AADPA, 2022)', 'Safren et al., Cognitive behavioral therapy vs relaxation with educational support for medication-treated adults with ADHD, JAMA, 2010', 'Beheshti et al., Emotion dysregulation in adults with ADHD: a meta-analysis, BMC Psychiatry, 2020'])

OT = dict(key='t-ot', icon='ph:puzzle-piece-duotone', hue=150, label='Track 3', title='Occupational therapy',
  blurb='Start from the occupations that fail, scaffold time and tasks, and fit the environment to the person.',
  scope=['Assess from the person’s own priorities, using a measure you can repeat.', 'Build external supports for time, sequence and memory, with the person rather than for them.', 'Advise on sensory load and reasonable adjustments at work and study.', 'Trial evidence for occupational therapy in adult ADHD is small. Measure your own outcomes and say so honestly.'],
  modules=[
   dict(title='Occupation-first assessment', lede='Begin with what the person needs to do, and where it breaks.', lessons=[
    ('Start with the COPM', ['The Canadian Occupational Performance Measure asks the person to name the daily activities that matter most and are going worst, then rate performance and satisfaction from 1 to 10. It turns “my life is chaos” into three to five specific targets.', 'Those ratings are your baseline and your outcome. A change of two points or more is generally regarded as clinically meaningful.'],
     ['Up to five problems, each rated 1 to 10 for performance and for satisfaction.', 'A change of two or more points is considered clinically meaningful.'],
     'Why begin with the COPM rather than a symptom checklist?', ['It diagnoses ADHD', 'It sets person-chosen, measurable occupational goals', 'It is quicker to score', 'It replaces the need for observation'], 'B', 'It anchors therapy in what the person needs to do, and gives a repeatable measure.'),
    ('Map the day', ['Walk through a typical weekday hour by hour. Look for the transitions: waking to leaving, arriving to starting, work to home. That is where most breakdowns sit.', 'Note what already works. A routine that survives without effort shows you the conditions under which this person succeeds, and you can copy those conditions elsewhere.'],
     ['Breakdowns cluster at transitions. Map those first.', 'Find what already works and borrow its conditions.'],
     'A client is reliably on time for football training but late for work. What is the most useful next step?', ['Tell him to care more about work', 'Conclude it is a motivation problem', 'Refer on', 'Identify what makes football work, such as a lift, fixed gear bag and teammates, and apply it to mornings'], 'D', 'Success conditions are transferable. That is the point of mapping the day.'),
    ('Analyse the task', ['Break a failing task into the executive demands it makes: starting, sequencing, estimating time, holding steps in mind, shifting, and stopping. The same “cannot do the washing” can be an initiation problem for one person and a sequencing problem for another.', 'Observe the task if you can. What people report and what they do often differ, and the difference is where the intervention goes.'],
     ['Name the executive demand that fails: start, sequence, time, memory, shift or stop.', 'Observe where possible. Report and performance differ.'],
     'A client starts cooking dinner but repeatedly abandons it halfway. Which demand is the most likely target?', ['Sustaining and sequencing through the middle of the task', 'Initiation', 'Motor skill', 'Knowledge of recipes'], 'A', 'She starts without trouble. The failure is in holding the sequence, so support goes there.')]),
   dict(title='Scaffolding time and tasks', lede='Make time visible, remove friction, and let the person build the strategy.', lessons=[
    ('Make time visible', ['Many adults with ADHD have a poor felt sense of time passing. Put time where it can be seen: analogue clocks in the rooms where time is lost, visual countdown timers, and alarms for transitions rather than only for deadlines.', 'Practise estimation. Guess how long a task will take, time it, compare. Repeated a few times a week, the gap narrows and plans become more realistic.'],
     ['Analogue clocks and visual timers where time is lost, usually bathroom and kitchen.', 'Estimate, time, compare: a short, repeatable calibration exercise.'],
     'A client is always surprised by how long her morning takes. What is the best first intervention?', ['Tell her to wake earlier', 'Buy a new planner', 'Time each step for a week, put a clock in the bathroom, and set transition alarms', 'Refer for medication review'], 'C', 'Measure the real durations, then make time visible at the point it disappears.'),
    ('Remove steps and friction', ['Put the cue where the action happens. Medication beside the kettle, keys on a hook by the door, a launch pad packed the night before. Each item has one home.', 'Then cut steps. Open shelving instead of lidded boxes, fewer clothes to choose from, bills on automatic payment. Every step removed is one less point of failure.'],
     ['Cues at the point of performance. One home for each essential item.', 'Reduce the number of steps before adding any new system.'],
     'A client keeps forgetting his medication, which is kept in a bathroom cabinet. What is the simplest effective change?', ['A more detailed reminder app', 'Move it beside something he does every morning, such as the kettle', 'A lecture on adherence', 'A weekly check-in call'], 'B', 'A cue tied to an existing habit at the point of performance beats a reminder that can be dismissed.'),
    ('Goal, plan, do, check', ['The CO-OP approach teaches one problem-solving routine: set the goal, make a plan, do it, check whether it worked. The therapist guides with questions. The person generates the strategy.', 'Strategies people invent themselves last longer than ones handed to them. Your skill is in asking the question that lets them find it.'],
     ['Goal, plan, do, check: one routine applied to every new problem.', 'Guide with questions. The person owns the strategy.'],
     'In CO-OP, a client’s first plan for paying bills on time fails. What comes next?', ['You give her the correct strategy', 'You conclude the approach is unsuitable', 'You move to a different goal', 'You ask what she noticed and help her revise her own plan'], 'D', 'Check then revise. The cycle, and the ownership, is the intervention.')]),
   dict(title='Environment, sensory load and work', lede='Change the setting when changing the person is the harder route.', lessons=[
    ('Sensory load', ['Open-plan noise, visual clutter, bright light and constant interruption all consume attention. Many adults with ADHD report sensory sensitivities, though research on sensory-based intervention in adult ADHD is thin.', 'Treat adjustments as low-cost trials: headphones, a desk facing away from traffic, notifications off for set blocks. Keep the ones that measurably help.'],
     ['Trial one adjustment at a time and re-rate the target activity.', 'Evidence is thin. Be clear that these are trials, not treatments.'],
     'A client says she cannot concentrate in her open-plan office. What is a sound approach?', ['Tell her to try harder', 'Recommend she resign', 'Trial specific adjustments one at a time and measure the effect on her work goal', 'Prescribe a sensory diet as proven treatment'], 'C', 'Cheap, reversible, measured trials are appropriate where evidence is limited.'),
    ('Adjustments at work and study', ['In Australia, the Disability Discrimination Act 1992 requires employers and education providers to make reasonable adjustments. ADHD can qualify. Disclosure is the person’s choice, and you can help them weigh it.', 'Useful adjustments are usually modest: written instructions, a quieter space, flexible start times, regular short check-ins, and deadlines broken into stages. JobAccess offers advice and may fund workplace modifications.'],
     ['Reasonable adjustments are a legal obligation under the Disability Discrimination Act 1992.', 'JobAccess: national advice line and possible funding for workplace changes.'],
     'A client wants adjustments but fears telling her manager she has ADHD. What is the best advice?', ['Disclosure is her choice; help her weigh it and frame requests around specific needs', 'She must disclose the diagnosis in full', 'She should never disclose', 'Adjustments are not available for ADHD'], 'A', 'She can request adjustments in terms of needs. Whether and how much to disclose is hers to decide.'),
    ('Home and admin', ['Household administration is where many adults with ADHD carry the most shame: unopened mail, late fees, expired registration. Automate what can be automated, and gather the rest into one short weekly session at a fixed time.', 'Doing that session alongside someone, in person or on a video call, makes starting far more likely. It is simple, free and worth suggesting early.'],
     ['Automate recurring payments. One fixed weekly admin session for the rest.', 'Working alongside another person helps with starting.'],
     'A client has three months of unopened mail. What is the best first step?', ['A new filing system', 'One supported session to sort it, then a fixed weekly slot with someone alongside', 'Advice to open mail daily', 'A referral to a financial counsellor only'], 'B', 'Clear the backlog with support, then prevent it rebuilding with a small fixed routine.')]),
   dict(title='Working with the team', lede='Use the medication window, re-measure, and know when to refer on.', lessons=[
    ('Use the medication window', ['You do not advise on medication, but you should know when it works. Ask what time it is taken and when it wears off. Schedule the hardest tasks, and your own sessions, inside that window.', 'If routines collapse in the evening, that may be the medicine wearing off. With consent, say so to the prescriber. It is useful information they may not have.'],
     ['Know the person’s coverage window and plan demanding tasks within it.', 'Report patterns you observe to the prescriber, with consent.'],
     'A client manages well until 4pm, then everything unravels. What do you do?', ['Tell her to take an extra dose', 'Ignore medication entirely', 'Assume she is tired', 'Plan key tasks earlier, and with consent tell the prescriber about the pattern'], 'D', 'Work within the window and pass the observation on. Dosing stays with the prescriber.'),
    ('Re-measure and report', ['Re-score the COPM at eight to twelve weeks. It tells you and the person whether the work is helping, and it is the number the referrer needs.', 'Write a short report: goals, baseline scores, what was tried, current scores, what happens next. One page is enough and far more likely to be read.'],
     ['Re-score at eight to twelve weeks and compare with baseline.', 'One-page report: goals, scores before and after, plan.'],
     'At ten weeks, performance has moved from 3 to 6 but satisfaction from 3 to 4. What does that suggest?', ['Therapy has failed', 'The scores are unreliable', 'Performance has improved, but something still matters to her that has not been addressed. Ask what', 'Discharge immediately'], 'C', 'A gap between performance and satisfaction is a prompt to ask what still matters.'),
    ('When to refer on', ['Refer to the GP or a psychologist for low mood, anxiety or any thoughts of self-harm. Refer for sleep assessment when sleep is short or irregular despite good routines. Persistent restriction or binge eating needs a dietitian or eating disorder service.', 'Say what you observed and what you are asking. Keep working on the occupational goals while the referral proceeds.'],
     ['Mood, risk, sleep and eating concerns go to the GP or relevant clinician promptly.', 'Refer with an observation and a question, and keep your own work going.'],
     'During a home visit a client tells you she has been thinking about ending her life. What do you do?', ['Follow your service’s risk pathway now and inform her GP', 'Note it for next session', 'Keep it confidential', 'Change the subject'], 'A', 'Disclosure of suicidal thoughts is acted on immediately, through your risk pathway and the GP.')]),
  ],
  sources=['Australian Evidence-Based Clinical Practice Guideline for ADHD (AADPA, 2022)', 'Canadian Occupational Performance Measure (COPM), 5th edition', 'JobAccess, Australian Government: workplace adjustments and the Employment Assistance Fund'])

EP = dict(key='t-ep', icon='ph:person-simple-run-duotone', hue=5, label='Track 4', title='Exercise physiology',
  blurb='Screen safely on stimulants, use exercise as a short-acting cognitive lever, and design programmes people keep doing.',
  scope=['Screen and prescribe safely for clients taking stimulant medication.', 'Use single sessions deliberately, and explain honestly how small and short the effect is.', 'Design for adherence, because that is where exercise programmes fail in ADHD.', 'Exercise is an adjunct. It does not replace assessment or first-line treatment.'],
  modules=[
   dict(title='Screen before you load', lede='Pre-exercise screening, the medication effect, and when to stop.', lessons=[
    ('Screening and the medication list', ['Use the Adult Pre-Exercise Screening System as you would for any client, and add a full medication list. Ask specifically about ADHD medicines, what time they are taken, and about caffeine, energy drinks and pre-workout supplements.', 'Record resting heart rate and blood pressure at the first visit. It gives you a baseline, and it gives the prescriber a useful outside measurement.'],
     ['Standard pre-exercise screening plus a full medicine and supplement list.', 'Resting heart rate and blood pressure recorded at baseline.'],
     'A new client takes lisdexamfetamine and uses a caffeine-based pre-workout. What is the first priority?', ['Ignore it; supplements are his business', 'Advise dropping the pre-workout, since it adds to the stimulant’s effect on heart rate and blood pressure', 'Double the warm-up', 'Refuse to train him'], 'B', 'Stimulant plus high-dose caffeine is additive. Removing the supplement is the simplest safety step.'),
    ('Stimulants change the numbers', ['Stimulant medication raises resting and exercising heart rate a little, so heart rate zones calculated from age may overstate effort. Use perceived exertion and the talk test alongside heart rate.', 'Appetite suppression means some clients arrive under-fuelled and under-hydrated, which matters more for them than the heart rate shift. Ask when they last ate.'],
     ['Prescribe intensity by perceived exertion and talk test, not heart rate alone.', 'Ask about food and fluid before every session.'],
     'A client on a stimulant hits her “maximum” heart rate zone while chatting comfortably. What is the best interpretation?', ['She is at maximal effort', 'The monitor is broken', 'She should stop immediately', 'Heart rate is elevated by medication; perceived exertion is the better guide here'], 'D', 'Comfortable speech indicates moderate effort. Trust exertion over the number.'),
    ('Red flags', ['Stop the session and refer for medical review if a client reports chest pain or tightness, fainting or near-fainting, palpitations that are new or sustained, or unusual breathlessness. The same applies if resting blood pressure is well above your screening thresholds.', 'Tell the GP or prescriber what you saw, with the numbers and the time of the last dose. Do not resume until they have been reviewed.'],
     ['Chest pain, fainting, sustained palpitations, unusual breathlessness: stop and refer.', 'Report with numbers and the time of the last medication dose.'],
     'Mid-session, a client on a stimulant reports sudden palpitations and light-headedness. What do you do?', ['Stop, monitor, and arrange medical review before any further exercise', 'Lower the intensity and carry on', 'Give water and continue', 'Suggest she skips tomorrow’s medication'], 'A', 'New cardiac symptoms on a stimulant need medical review first. Medication advice is not yours to give.')]),
   dict(title='Exercise as a state lever', lede='What a single session does, what a programme does, and when to place it.', lessons=[
    ('The single session', ['A single bout of moderate aerobic exercise, around 20 to 30 minutes, produces a small to moderate improvement in attention and executive function for roughly the following hour. Most studies are in children and young adults, and many are small.', 'That makes exercise a useful short-acting tool with a modest effect. It is not a treatment for ADHD, and it should not be described as one.'],
     ['About 20 to 30 minutes of moderate aerobic work; benefit lasts around an hour.', 'Effect sizes are small to moderate, from mostly small studies.'],
     'A client asks whether exercise can replace his medication. What is an accurate answer?', ['Yes, if he trains hard enough', 'No benefit at all', 'Exercise gives a modest, short-lived lift in attention and is a useful addition, not a replacement; medication decisions are for his prescriber', 'Only weights help'], 'C', 'Be accurate about the size of the effect, and keep medication decisions with the prescriber.'),
    ('The longer programme', ['Programmes lasting weeks to months show small improvements in attention, mood and sleep, with wide variation between studies. The benefits for cardiovascular health, sleep and mood are well established in adults generally and are reason enough.', 'Set expectations accordingly: a client should expect to feel and sleep somewhat better, not to have their ADHD resolved.'],
     ['Expect modest gains in mood, sleep and attention, with wide individual variation.', 'General health benefits are well established and sufficient justification.'],
     'Which goal is the most realistic to agree with a new client?', ['Eliminating ADHD symptoms', 'Better sleep, mood and energy, with some help for focus', 'Stopping medication in three months', 'Guaranteed weight loss'], 'B', 'Goals should match the evidence: real, modest benefits.'),
    ('Timing', ['Because the cognitive lift is short, place sessions before demanding mental work: a morning session before the working day, or a brisk 20 minutes before study. Ask what time medication is taken and plan around appetite and energy.', 'Hard training late in the evening can delay sleep for some people. If sleep is already short, move it earlier.'],
     ['Schedule exercise immediately before the hardest mental work of the day.', 'Avoid hard late-evening sessions when sleep onset is a problem.'],
     'A university student struggles most with afternoon study. When is exercise most useful?', ['Late at night', 'Only at weekends', 'First thing, six hours earlier', 'A brisk 20 to 30 minutes just before the afternoon study block'], 'D', 'The effect lasts about an hour, so place it directly before the demanding task.')]),
   dict(title='Adherence by design', lede='Why programmes fail in ADHD and how to build one that lasts.', lessons=[
    ('Why people stop', ['Dropout in ADHD is rarely about motivation. It is about planning, remembering, getting started, boredom with repetition, and rewards that arrive too far in the future. These are the core difficulties of the condition.', 'So a standard 12-week progressive programme, handed over on paper, is close to the worst possible design. Assume the barrier is executive, and design around it.'],
     ['Expect barriers in planning, starting, remembering and boredom.', 'A missed session is information about the design, not about the person.'],
     'A client with ADHD has stopped attending after three weeks. What is the most useful assumption?', ['The programme design did not fit; find which step broke', 'She lacks motivation', 'Exercise does not suit her', 'She should be discharged'], 'A', 'Look for the step that failed, such as packing the bag or booking the slot, and fix that.'),
    ('Design features that help', ['Keep sessions short and varied. Book them at a fixed time with another person, a class or a training partner, so that someone is expecting them. Give immediate feedback: a number, a streak, something visible today.', 'Reduce set-up to nearly nothing: a bag packed the night before, a venue on the route home, a routine that needs no decisions.'],
     ['Short, varied, fixed-time sessions with another person expecting them.', 'Immediate feedback and near-zero set-up.'],
     'Which programme is most likely to last for an adult with ADHD?', ['A detailed 12-week plan to follow alone at home', 'Long sessions twice a month', 'Two fixed weekly sessions with a partner, varied content, and a visible streak', 'Whenever she feels like it'], 'C', 'Social commitment, variety, fixed timing and immediate feedback all address the known barriers.'),
    ('Planning for lapses', ['Lapses are certain. Agree in advance on a minimum session, ten minutes counts, and a simple rule such as never missing twice in a row. Rehearse the restart so it does not need a fresh decision.', 'When a client returns after a gap, welcome them without comment and lower the load. Shame is what turns a missed week into a missed year.'],
     ['A defined minimum session and a “never miss twice” rule.', 'Return after a lapse: no commentary, reduced load, rebook on the spot.'],
     'A client returns sheepishly after a five-week gap. What is the best response?', ['Ask her to explain the absence', 'Welcome her, reduce the load, and book the next two sessions before she leaves', 'Restart at the previous load', 'Warn her about commitment'], 'B', 'Remove shame and friction. Rebook immediately while she is there.')]),
   dict(title='Working with the team', lede='What to report, fuelling on stimulants, and handing over.', lessons=[
    ('What to tell the prescriber', ['You take more blood pressure and heart rate readings than anyone else in the team. With consent, send trends to the GP or prescriber, especially resting values that are climbing, any symptoms, and unintended weight loss.', 'Keep it brief and numerical, and include the usual time of the medication dose. You are reporting, not advising on dose.'],
     ['Report resting heart rate and blood pressure trends, symptoms and weight change.', 'Include dose timing. Leave dosing decisions to the prescriber.'],
     'Over six weeks a client’s resting blood pressure has risen steadily since her dose was increased. What do you do?', ['Tell her to reduce her dose', 'Say nothing; it is outside your scope', 'Stop all exercise permanently', 'With consent, send the readings and dates to her prescriber'], 'D', 'Reporting the trend is squarely within scope and genuinely useful. Dosing is not yours to change.'),
    ('Fuel and hydration', ['Stimulants suppress appetite through the middle of the day, so clients often train having eaten little since breakfast. Signs include light-headedness, poor session quality and unplanned weight loss.', 'Encourage a proper breakfast before the morning dose and a planned snack before training. Refer to a dietitian when weight is falling or eating looks restricted.'],
     ['Ask what and when the client last ate, every session.', 'Falling weight or restricted eating: refer to a dietitian.'],
     'A client feels faint in afternoon sessions and has lost four kilograms unintentionally. What is the best action?', ['Push through with lighter weights', 'Refer to a dietitian, inform the GP, and adjust sessions in the meantime', 'Recommend a protein supplement and continue', 'Train her fasted to adapt'], 'B', 'Unintended weight loss on a stimulant needs dietetic and medical attention, not just a snack.'),
    ('Shared goals and handover', ['Use the same goals as the rest of the team where you can. If the occupational therapist is working on mornings, a morning session supports that goal directly.', 'At discharge, hand over a programme the client can run alone: short, written on one page, with the restart rule on it. Tell the referrer what changed, in numbers.'],
     ['Align sessions with the goals the team is already measuring.', 'Discharge with a one-page programme that includes the restart rule.'],
     'Which discharge summary is the most useful to a GP?', ['“Client did well.”', '“Completed programme.”', '“Attended 14 of 16 sessions; resting heart rate 78 to 70; sleep rating 4 to 7; continuing two sessions a week with a partner.”', '“Discharged.”'], 'C', 'Numbers, change and the ongoing plan are what a referrer can use.')]),
  ],
  sources=['Exercise and Sports Science Australia: Adult Pre-Exercise Screening System', 'Australian Evidence-Based Clinical Practice Guideline for ADHD (AADPA, 2022)', 'See Module 06 of this course for the evidence on acute exercise and cognition'])

NUT = dict(key='t-nut', icon='ph:leaf-duotone', hue=110, label='Track 5', title='Nutrition',
  blurb='Appetite on stimulants, eating structures that survive ADHD, and an honest account of the diet evidence.',
  scope=['Support regular, adequate eating for people whose appetite and planning are both affected.', 'Screen for disordered eating and refer early.', 'Explain what diet and supplements can and cannot do, without overselling.', 'Medical nutrition therapy and eating disorders belong with an Accredited Practising Dietitian. Know the limits of your own scope.'],
  modules=[
   dict(title='Scope and screening', lede='Where you fit, the appetite problem, and the red flags.', lessons=[
    ('Where you fit', ['Your contribution is practical: helping people eat regularly and adequately when both their appetite and their planning are working against them. That is valuable, and it is often the thing nobody else in the team has time for.', 'You do not diagnose ADHD, and you do not advise on medication. In Australia, medical nutrition therapy and eating disorder treatment sit with Accredited Practising Dietitians. Refer when a client’s needs go beyond general nutrition advice.'],
     ['Role: regular, adequate, low-effort eating. Not diagnosis, not medication advice.', 'Eating disorders and medical nutrition therapy: refer to an Accredited Practising Dietitian.'],
     'A client asks whether she should stop her ADHD medication because it ruins her appetite. What do you say?', ['Yes, appetite matters more', 'No, never stop it', 'Try halving it', 'That decision is for her prescriber; you will help with eating strategies and suggest she raises it at her next review'], 'D', 'Medication decisions stay with the prescriber. Your part is the eating strategy and encouraging the conversation.'),
    ('The appetite problem', ['Reduced appetite is the most common side effect of stimulant medication. Hunger typically disappears through the middle of the day and returns hard in the evening, which produces skipped lunches followed by large, late meals.', 'Track weight. Unintended loss of more than about five per cent of body weight over three months is a signal to involve the GP.'],
     ['Expect low midday appetite and strong evening hunger on stimulants.', 'Unintended loss of around five per cent in three months: tell the GP.'],
     'A client on a stimulant eats nothing between breakfast and 8pm, then overeats. What best explains it?', ['Poor willpower', 'A predictable effect of the medication’s appetite suppression wearing off', 'An eating disorder, certainly', 'Food intolerance'], 'B', 'This is the usual stimulant pattern. Plan for it rather than moralise about it.'),
    ('Disordered eating', ['ADHD is associated with higher rates of binge eating and bulimia. Impulsivity, irregular meals and using food for stimulation all contribute. Restriction can also hide behind “the medication took my appetite”.', 'Ask directly and without judgement. A brief screen such as the five SCOFF questions helps: two or more positive answers suggest a likely eating disorder and the need to refer.'],
     ['SCOFF: two or more positive answers warrants referral.', 'Ask about bingeing, purging and deliberate restriction, not only appetite.'],
     'A client answers yes to three SCOFF questions. What is the next step?', ['Refer to her GP and an eating disorder-experienced dietitian', 'Start a meal plan yourself', 'Reassure her', 'Recommend a weight-loss programme'], 'A', 'A positive screen needs medical and specialist dietetic assessment, not general advice.')]),
   dict(title='Eating structure that survives ADHD', lede='Plan around the medication and remove as many decisions as possible.', lessons=[
    ('Eat before the dose', ['The most reliable window for a proper meal is before the morning medication takes effect. A breakfast with protein and some fat, eaten before or with the dose, protects against the long appetite gap that follows.', 'This is practical consensus rather than trial evidence, but it is cheap, safe and works for many people.'],
     ['A substantial breakfast with protein, before or with the morning dose.', 'Practical consensus: low risk, no strong trial evidence.'],
     'When is a person on a morning stimulant most likely to manage a full meal?', ['Mid-afternoon', 'At midday', 'Before the dose takes effect, and again in the evening', 'They cannot'], 'C', 'Appetite is best before the medication starts and after it wears off. Plan the main meals there.'),
    ('Eat by the clock', ['When hunger cues are unreliable, eat by the clock instead. Set alarms for a mid-morning and a lunchtime eating occasion, and treat them as appointments.', 'Aim for small, energy-dense food that needs no preparation: yoghurt, nuts, cheese and crackers, a smoothie. A little eaten is better than a meal skipped.'],
     ['Alarms for eating occasions when hunger cues are absent.', 'Small, energy-dense, no-preparation foods through the day.'],
     'A client says she simply does not feel hungry at lunch. What is the best strategy?', ['Wait until she is hungry', 'A scheduled small, energy-dense snack at a set time, by alarm', 'A large lunch regardless', 'Skip lunch and eat more at dinner'], 'B', 'Schedule replaces appetite. Small and energy-dense is achievable when hunger is absent.'),
    ('Make food low-effort', ['Meal planning, shopping and cooking all lean heavily on executive function. Lower the load: a short list of default meals, a saved online grocery order, frozen vegetables, pre-cooked grains, and cooking double to freeze.', 'Avoid elaborate meal plans. If the plan needs a good week to work, it will fail in a bad one, and the bad weeks are when it matters.'],
     ['Five default meals and a saved grocery order beat a detailed weekly plan.', 'Design for the bad week, not the good one.'],
     'Which recommendation is most likely to still be in use after three months?', ['A colour-coded 28-day meal plan', 'Daily fresh shopping', 'Cooking every meal from scratch', 'A saved grocery order and five default meals that take under 15 minutes'], 'D', 'Few decisions and little effort are what survive.')]),
   dict(title='The evidence, honestly', lede='What diet and supplements can and cannot do for ADHD.', lessons=[
    ('Omega-3', ['Meta-analyses of omega-3 supplementation show at best a small improvement in ADHD symptoms, mostly in children, and much smaller than the effect of medication. Findings are inconsistent between trials.', 'It is safe for most people and reasonable to try if a client wishes, as an addition to their treatment. It should not be presented as a treatment for ADHD.'],
     ['Small effect at best, mainly in children, far below medication.', 'Reasonable as an addition. Not a treatment, and not a replacement.'],
     'A client wants to use fish oil instead of starting medication. What is accurate advice?', ['The evidence shows only a small benefit; it will not replace medication, and the decision about medication is one to make with her doctor', 'Fish oil works as well as medication', 'Fish oil is dangerous', 'She must take medication'], 'A', 'State the size of the effect honestly and keep the medication decision with her doctor.'),
    ('Elimination diets, additives and sugar', ['Restrictive “few foods” diets have helped a minority of children in trials, but the studies have weaknesses, the diets are demanding, and there is little evidence in adults. They also carry a real risk of nutritional inadequacy and disordered eating.', 'Sugar does not cause ADHD. Controlled studies have not shown that it worsens behaviour. Some children appear sensitive to certain artificial colours, but this is not a basis for routine restriction in adults.'],
     ['Elimination diets: not recommended routinely for adults; supervise closely if used at all.', 'Sugar has not been shown to cause or worsen ADHD.'],
     'A client proposes a strict elimination diet to manage her ADHD. What is the best response?', ['Encourage it enthusiastically', 'Tell her diet is irrelevant to health', 'Explain the limited adult evidence and the risks, and offer regular, adequate eating as the priority', 'Provide a list of foods to eliminate'], 'C', 'Be honest about limited evidence and real risks, and redirect to what reliably helps.'),
    ('Micronutrients and caffeine', ['Low iron, zinc, vitamin D and magnesium have each been linked with ADHD in observational studies. The sensible approach is to test where deficiency is plausible and correct what is low. There is no good evidence for high doses in people who are not deficient, and iron in particular should never be supplemented blind.', 'Caffeine adds to the effect of stimulant medication on heart rate, anxiety and sleep. Ask how much, and when.'],
     ['Test first, then correct deficiency. No routine high-dose supplementation.', 'Caffeine plus stimulant: additive effects on heart rate, anxiety and sleep.'],
     'A client taking a stimulant drinks four energy drinks a day and sleeps poorly. What is the most useful advice?', ['Add magnesium', 'Reduce caffeine, especially after midday, and mention it to her prescriber', 'Add an iron supplement', 'Nothing; caffeine is unrelated'], 'B', 'High caffeine with a stimulant is a likely and fixable contributor to poor sleep.')]),
   dict(title='Working with the team', lede='What to pass on, shared goals, and how to talk about evidence.', lessons=[
    ('What to tell the GP', ['With consent, let the GP or prescriber know about unintended weight loss, persistently poor intake, any sign of disordered eating, and every supplement the client takes. Supplements are often not mentioned to doctors.', 'Keep it short: what you observed, the numbers, what you have advised.'],
     ['Report weight loss, poor intake, disordered eating signs and the supplement list.', 'Brief, factual, with numbers.'],
     'A client has lost six per cent of her body weight in ten weeks on a new stimulant. What do you do?', ['Increase her snacks and review in three months', 'Congratulate her', 'Suggest a weight-gain supplement only', 'With consent, inform the prescriber promptly, and continue eating support'], 'D', 'That rate of unintended loss needs the prescriber’s attention, alongside your support.'),
    ('Shared goals', ['Tie your work to a goal the client and team already care about: energy in the afternoon, fewer evening binges, stable weight. Rate it at the start and again at each review.', 'Small, specific changes are the right size. One new breakfast, held for a month, is worth more than a full dietary overhaul abandoned in a week.'],
     ['One or two goals, rated at baseline and at each review.', 'One change held for a month beats ten attempted for a week.'],
     'Which goal is best framed?', ['“Eat better.”', '“Follow a healthy diet.”', '“Breakfast with protein before my dose, five days in seven, for four weeks.”', '“Lose weight.”'], 'C', 'Specific, small, time-bound and tied to the medication pattern.'),
    ('Talking about evidence', ['Clients arrive having read confident claims about diet curing ADHD. Dismissing them damages trust. Overselling does more harm. Say what is known, how strong it is, and what you would suggest instead.', 'A useful form of words: “There is some evidence, the effect is small, and it would be in addition to your treatment, not instead of it.”'],
     ['State what is known and how strong the evidence is, plainly.', 'Offer an alternative action, not just a “no”.'],
     'A client says a website claims a supplement “reverses ADHD”. What is the best response?', ['Agree, to keep rapport', 'Explain what the evidence actually shows, without ridicule, and suggest what is more likely to help', 'Tell her it is nonsense', 'Refuse to discuss it'], 'B', 'Honest, respectful correction keeps trust and points to something useful.')]),
  ],
  sources=['Australian Evidence-Based Clinical Practice Guideline for ADHD (AADPA, 2022)', 'Dietitians Australia: finding an Accredited Practising Dietitian', 'Morgan, Reid and Lacey, The SCOFF questionnaire, BMJ, 1999'])

NAT = dict(key='t-nat', icon='ph:plant-duotone', hue=80, label='Track 6', title='Naturopathy',
  blurb='Safe scope alongside medical treatment, herb and medicine interactions, and an honest account of the evidence.',
  scope=['Work as an adjunct to medical care, never as an alternative to it.', 'Recognise red flags and refer promptly.', 'Know which herbs and supplements interact with ADHD medicines.', 'Be honest about evidence. Most complementary treatments for ADHD have little or none, and saying so protects your clients.'],
  modules=[
   dict(title='Scope and safety', lede='Where you fit, when to refer, and what to ask.', lessons=[
    ('Where you fit', ['Diagnosis of ADHD and decisions about prescribed medication belong to medical practitioners. Your contribution is as an adjunct: supporting sleep, regular eating, movement and stress, and keeping the client connected to their medical care.', 'Never advise a client to stop, reduce or delay prescribed ADHD medication. If a client wants to change it, help them take that to their prescriber.'],
     ['Adjunct to medical care. Not an alternative, and not a route around it.', 'Never advise stopping, reducing or delaying prescribed medication.'],
     'A client wants to stop her ADHD medication and “go natural”. What is the right response?', ['Support her and design a herbal protocol', 'Tell her to taper over two weeks', 'Suggest she halves it first', 'Encourage her to discuss it with her prescriber first, and offer to support her alongside whatever they decide'], 'D', 'Changes to prescribed medication are made with the prescriber. Your role is alongside.'),
    ('Red flags', ['Refer urgently for any thoughts of suicide or self-harm, for chest pain, fainting or palpitations in someone taking a stimulant, and for signs of mania or psychosis such as days without sleep, racing thoughts or unusual beliefs.', 'Refer promptly for rapid unintended weight loss, suspected eating disorder, pregnancy or planned pregnancy, and for anyone with suspected but undiagnosed ADHD. Assessment is the first step, not supplementation.'],
     ['Urgent: suicidal thoughts, cardiac symptoms on a stimulant, mania or psychosis.', 'Undiagnosed but suspected ADHD: refer for assessment before anything else.'],
     'A new client believes she has ADHD and asks for herbs to treat it. What do you do first?', ['Begin a herbal protocol', 'Recommend she sees her GP for assessment, and offer general wellbeing support meanwhile', 'Order functional testing', 'Tell her ADHD is overdiagnosed'], 'B', 'Assessment comes first. Treating an undiagnosed condition delays proper care.'),
    ('Ask about everything', ['Take a complete list: prescribed medicines, over-the-counter products, herbs, supplements, energy drinks, pre-workout powders and recreational substances. Clients often do not think of these as things that matter.', 'Record the ADHD medicine, the dose and the time it is taken. You cannot check for interactions with a medicine you do not know about.'],
     ['Full list of medicines, supplements, caffeine and substances at the first visit.', 'Record the ADHD medicine, dose and timing.'],
     'Why does the time a stimulant is taken matter to you?', ['It shows when its effects on appetite, heart rate and sleep occur, which shapes any advice you give', 'It does not matter', 'So you can change it', 'For billing purposes'], 'A', 'Timing explains appetite and sleep patterns. Changing it remains the prescriber’s decision.')]),
   dict(title='Herbs, supplements and ADHD medicines', lede='The interactions that matter, and what to avoid.', lessons=[
    ('Stimulant-like products', ['Several common products raise heart rate and blood pressure, and add to the effect of stimulant medication: guarana, high-dose caffeine, bitter orange or synephrine, yohimbe, and ephedra, which is not legally available in Australia.', 'Avoid recommending any of these to a client taking a stimulant, and check “energy”, “fat-burning” and “pre-workout” blends, which often contain several at once.'],
     ['Avoid with stimulants: guarana, high-dose caffeine, bitter orange, yohimbe, ephedra.', 'Read blended product labels. Stimulants hide in “energy” and “fat burner” formulas.'],
     'A client on dexamfetamine asks about a “natural energy” blend containing guarana and bitter orange. What do you advise?', ['It is natural, so it is safe', 'Take half the recommended amount', 'Avoid it: both ingredients add to the stimulant’s effect on heart rate and blood pressure', 'Take it in the evening instead'], 'C', 'These are additive with stimulant medication. Natural does not mean inert.'),
    ('St John’s wort and liquorice', ['St John’s wort speeds up the breakdown of many medicines and can make them less effective, including the oral contraceptive pill. It also acts on serotonin, so combining it with antidepressants risks serotonin toxicity. Many adults with ADHD take an antidepressant.', 'Liquorice root in regular or large amounts can raise blood pressure, which matters for anyone on a stimulant. Check with a pharmacist before combining any herb with prescribed medicines.'],
     ['St John’s wort: reduces the effect of many medicines; do not combine with antidepressants.', 'Liquorice can raise blood pressure. When unsure, ask a pharmacist.'],
     'A client taking a stimulant, an SSRI antidepressant and the contraceptive pill asks about St John’s wort for mood. What is correct?', ['It is a safe addition', 'It is fine in tea form', 'It only interacts with the stimulant', 'Advise against it: it risks serotonin toxicity with the SSRI and can make the pill less effective'], 'D', 'Two clinically important interactions, either of which is reason enough to avoid it.'),
    ('Sleep and calming herbs', ['Sleep problems are common in ADHD, and clients will ask for help. Kava carries warnings about rare but serious liver injury. Valerian and similar sedating herbs add to the effect of alcohol and other sedatives. Evidence that any of them improves sleep in ADHD is weak.', 'In Australia, melatonin is a scheduled medicine and is a matter for the prescriber or pharmacist. Your most useful contribution is sleep regularity: fixed wake time, morning light, less evening caffeine and screen use.'],
     ['Kava: liver warnings. Sedating herbs add to alcohol and other sedatives.', 'Melatonin is a scheduled medicine in Australia. Lead with sleep routine instead.'],
     'A client taking a stimulant cannot fall asleep before 1am. What is your best contribution?', ['A strong sedative herbal blend', 'Work on sleep regularity and evening caffeine, and suggest she tells her prescriber, since dose timing may be the cause', 'Advise her to take her medication later', 'Recommend melatonin at a dose you choose'], 'B', 'Routine is within your scope, and late dosing is a common cause that only the prescriber can address.')]),
   dict(title='The evidence, honestly', lede='What has some support, what is thin, and what has none.', lessons=[
    ('What has some support', ['Omega-3 supplementation shows a small benefit at best, mainly in children, and much smaller than medication. Correcting a confirmed deficiency of iron, zinc or vitamin D is sensible general care, and deficiency should be confirmed by testing through the GP before supplementing.', 'Beyond these, the things with the best evidence for wellbeing in ADHD are not supplements: regular sleep, regular meals and regular exercise.'],
     ['Omega-3: small effect. Correct confirmed deficiencies only.', 'Sleep, meals and movement have better support than any supplement.'],
     'Which statement to a client is accurate?', ['“Omega-3 may help a little alongside your treatment; it is not a substitute for it.”', '“Omega-3 treats ADHD.”', '“Zinc works for everyone with ADHD.”', '“Supplements are better than medication.”'], 'A', 'Accurate about the size of the effect and clear that it is an addition.'),
    ('What is thin', ['Saffron, French maritime pine bark extract, bacopa and ginkgo have each been tested in a handful of small, short trials, mostly in children. Some results look encouraging, but the studies are too few and too small to rely on, and long-term safety alongside ADHD medicines is largely unknown.', 'If a client chooses to try one, agree on a target, a time limit and a review date, and make sure the prescriber knows.'],
     ['Small, short, mostly paediatric trials. Promising is not proven.', 'If trialled: one product, a target, a time limit, and the prescriber informed.'],
     'A client asks whether saffron “works as well as Ritalin”, as she has read. What is an honest answer?', ['Yes, that is established', 'Saffron is dangerous', 'It works better', 'A couple of small, short studies suggested it; that is far too little to rely on, and nowhere near the evidence behind her medication'], 'D', 'Be specific about how little evidence there is, without dismissing the question.'),
    ('What has no good evidence', ['Homeopathy has no reliable evidence of effectiveness for any health condition, according to the National Health and Medical Research Council’s 2015 review. “Detox” programmes, high-dose vitamin regimens and most functional testing panels have no support in ADHD.', 'These approaches are not harmless. They cost money, and they can delay effective care. Telling a client plainly that something will not help is part of looking after them.'],
     ['Homeopathy, detoxes and megavitamins: no good evidence in ADHD.', 'Cost and delay of effective treatment are real harms.'],
     'A parent asks you about a homeopathic remedy for her adult son’s ADHD. What is the most ethical response?', ['Supply it, since it cannot hurt', 'Recommend it alongside a detox', 'Explain that there is no reliable evidence it works, and steer towards assessment and approaches that do help', 'Avoid answering'], 'C', 'Honesty about ineffective treatments protects the client’s money and time.')]),
   dict(title='Working with the team', lede='Communicate, focus on foundations, and review.', lessons=[
    ('Write to the GP', ['With the client’s consent, send the GP a short note listing what you have recommended: product, dose and start date. Doctors are often unaware of what their patients take, and the combination is what creates risk.', 'This also builds trust. A naturopath who communicates openly is one a GP will be willing to work with.'],
     ['Product, dose and start date, sent to the GP with consent.', 'Open communication is what makes shared care possible.'],
     'Why tell a client’s GP about a magnesium supplement you have recommended?', ['You are required to ask permission to practise', 'So the full list of what she takes is known to the person prescribing her medicines', 'It is not necessary', 'To transfer responsibility'], 'B', 'Safe prescribing depends on knowing everything the patient takes.'),
    ('Foundations first', ['The areas where you can add the most are the unglamorous ones: a consistent wake time, breakfast before the morning dose, less caffeine after midday, daily movement, and a wind-down routine. These have better support than any product you could recommend.', 'Keep changes small and few. People with ADHD are often handed long protocols they cannot sustain, and the failure lands on them as more shame.'],
     ['Sleep regularity, regular meals, movement and caffeine timing come first.', 'One or two changes at a time. Long protocols fail.'],
     'What is the most useful first recommendation for a newly diagnosed adult?', ['A twelve-product supplement protocol', 'An elimination diet', 'A week-long detox', 'A consistent wake time and breakfast before her medication'], 'D', 'Simple foundations have the best support and the best chance of being kept up.'),
    ('Review and stop', ['Set a review date for anything you recommend, usually eight to twelve weeks, with a target agreed at the start. If it has not helped by then, stop it. A growing list of supplements with no clear benefit is poor care.', 'Use the same goals the rest of the team is tracking where you can, so that everyone is looking at the same change.'],
     ['Every recommendation has a target and a review date.', 'No benefit at review: stop it.'],
     'At a twelve-week review, a supplement has made no difference to the agreed target. What do you do?', ['Stop it, and revisit the foundations', 'Double the dose', 'Add two more products', 'Continue indefinitely'], 'A', 'Stopping what does not work is as important as starting what might.')]),
  ],
  sources=['Australian Evidence-Based Clinical Practice Guideline for ADHD (AADPA, 2022)', 'National Health and Medical Research Council, Evidence on the effectiveness of homeopathy for treating health conditions, 2015', 'Therapeutic Goods Administration: safety information on kava and on St John’s wort interactions'])

TRACKS = [GP, PSY, OT, EP, NUT, NAT]
